package br.com.orientec.backend.adapter.out.persistence.entity.os;
import br.com.orientec.backend.adapter.out.persistence.entity.os.*;
import br.com.orientec.backend.adapter.out.persistence.repository.os.*;
import br.com.orientec.backend.application.service.os.*;
import br.com.orientec.backend.adapter.out.persistence.entity.usuario.Usuario; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="ordem_servico") public class OrdemServico {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="situacao_id",nullable=false) private OsStatus situacao;
 @Column(name="cliente_id") private Integer clienteId; @Column(name="equipamento_modelo_id") private Integer equipamentoModeloId; @Column(name="origem_id") private Short origemId; @Column(name="tipo_garantia_id") private Short tipoGarantiaId;
 @Column(name="responsavel_codigo") private Long responsavelCodigo; @Column(name="sede_atual_codigo") private Long sedeAtualCodigo; @Column(name="criado_por") private Long criadoPor;
 @Column(name="data_abertura") private LocalDate dataAbertura; @Column(name="hora_abertura") private LocalTime horaAbertura; @Column(name="defeito_relatado") private String defeitoRelatado; @Column(name="observacao") private String observacao;
 @Column(name="aguar_pecas",nullable=false) private boolean aguardaPecas; @Column(name="aguar_fotos",nullable=false) private boolean aguardaFotos; @Column(name="aguar_nota",nullable=false) private boolean aguardaNota;
 @Column(name="envio_credenciado",nullable=false) private boolean envioCredenciado; @Column(name="data_envio_credenciado") private OffsetDateTime dataEnvioCredenciado; @Column(name="data_entrega") private OffsetDateTime dataEntrega; @Column(name="entregue_por") private Long entreguePor;
 @Column(name="criado_em",nullable=false) private OffsetDateTime criadoEm; @Column(name="atualizado_em",nullable=false) private OffsetDateTime atualizadoEm; @Version private Long version;
 public OrdemServico(){} @PrePersist void pre(){if(criadoEm==null)criadoEm=OffsetDateTime.now(); if(atualizadoEm==null)atualizadoEm=criadoEm;} @PreUpdate void upd(){atualizadoEm=OffsetDateTime.now();}
 public Long getId(){return id;} public OsStatus getSituacao(){return situacao;} public Integer getClienteId(){return clienteId;} public Integer getEquipamentoModeloId(){return equipamentoModeloId;} public Short getOrigemId(){return origemId;} public Short getTipoGarantiaId(){return tipoGarantiaId;} public Long getResponsavelCodigo(){return responsavelCodigo;} public Long getSedeAtualCodigo(){return sedeAtualCodigo;} public Long getCriadoPor(){return criadoPor;} public LocalDate getDataAbertura(){return dataAbertura;} public LocalTime getHoraAbertura(){return horaAbertura;} public String getDefeitoRelatado(){return defeitoRelatado;} public String getObservacao(){return observacao;} public boolean isAguardaPecas(){return aguardaPecas;} public boolean isAguardaFotos(){return aguardaFotos;} public boolean isAguardaNota(){return aguardaNota;} public boolean isEnvioCredenciado(){return envioCredenciado;} public OffsetDateTime getDataEnvioCredenciado(){return dataEnvioCredenciado;} public OffsetDateTime getDataEntrega(){return dataEntrega;} public Long getEntreguePor(){return entreguePor;} public OffsetDateTime getCriadoEm(){return criadoEm;} public OffsetDateTime getAtualizadoEm(){return atualizadoEm;} public Long getVersion(){return version;}
 public void setSituacao(OsStatus v){situacao=v;} public void setClienteId(Integer v){clienteId=v;} public void setEquipamentoModeloId(Integer v){equipamentoModeloId=v;} public void setOrigemId(Short v){origemId=v;} public void setTipoGarantiaId(Short v){tipoGarantiaId=v;} public void setResponsavelCodigo(Long v){responsavelCodigo=v;} public void setSedeAtualCodigo(Long v){sedeAtualCodigo=v;} public void setCriadoPor(Long v){criadoPor=v;} public void setDataAbertura(LocalDate v){dataAbertura=v;} public void setHoraAbertura(LocalTime v){horaAbertura=v;} public void setDefeitoRelatado(String v){defeitoRelatado=v;} public void setObservacao(String v){observacao=v;} public void setAguardaPecas(boolean v){aguardaPecas=v;} public void setAguardaFotos(boolean v){aguardaFotos=v;} public void setAguardaNota(boolean v){aguardaNota=v;} public void setEnvioCredenciado(boolean v){envioCredenciado=v;} public void setDataEntrega(OffsetDateTime v){dataEntrega=v;} public void setEntreguePor(Long v){entreguePor=v;}
 public void mudarSituacao(OsStatus destino){this.situacao=destino;}
}
